<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <link rel="icon" type="image/svg+xml" href="data:image/svg+xml;base64," />
    <meta name="robots" content="index, follow" />
    <title><?= htmlspecialchars($title ?? 'Документация') ?></title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Manrope:wght@200..800&display=swap" rel="stylesheet">
    <style>
        :root {
            --primary: #E6E9EE;
            --secondary: #ADB3BD;
            --black: #0B0D10;
            --green: #6EE7B7;
            --blue: #6BA7FF;
            --red: #FF6B6B;
            --background: rgba(255, 255, 255, 0.04);
            --background-blue: rgba(107, 166, 255, 0.2);
            --background-green: rgba(110, 231, 183, 0.2);
            --background-white: rgba(173, 179, 189, 0.5);
            --background-blue-light: rgba(107, 167, 255, 0.06);
            --background-green-light: rgba(110, 231, 183, 0.04);
            --spacer: rgba(255, 255, 255, 0.2);
            --sidebar-width: 280px;
            --header-height: 60px;
        }

        * {
            box-sizing: border-box;
        }

        body {
            margin: 0;
            background-color: var(--black);
            color: var(--primary);
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            display: flex;
            flex-direction: column;
            min-height: 100vh;
            overflow-x: hidden;
        }

        .layout {
            display: flex;
            flex: 1 0 auto;
            position: relative;
        }

        /* --- Sidebar --- */
        .sidebar {
            width: var(--sidebar-width);
            flex-shrink: 0;
            background: var(--background);
            border-right: 1px solid var(--spacer);
            transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            z-index: 50;
        }

        .sidebar.collapsed {
            width: 0;
            border-right: none;
        }

        .sidebar-header {
            height: var(--header-height);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 20px;
            background: transparent;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            white-space: nowrap;
        }

        /* Состояние "острова" при закрытом сайдбаре */
        .sidebar.collapsed .sidebar-header {
            position: absolute;
            top: 10px;
            left: 16px;
            background: var(--background-green-light);
            border: 1px solid var(--spacer);
            border-radius: 13px;
            padding: 0 16px;
            width: calc(280px - 32px);
            box-shadow: 0 4px 24px rgba(0, 0, 0, 0.4);
            z-index: 100;
        }

        .logo {
            display: flex;
            align-items: center;
            font-weight: 600;
            font-size: 16px;
            color: var(--primary);
            text-decoration: none;
        }

        .logo svg {
            color: var(--blue);
        }

        .toggle-sidebar {
            background: transparent;
            border: none;
            color: var(--secondary);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 6px;
            border-radius: 6px;
            transition: background 0.2s, color 0.2s;
        }

        .toggle-sidebar:hover {
            background: var(--background-white);
            color: var(--primary);
        }

        .sidebar-content {
            padding: 20px 0;
            overflow-y: auto;
            height: calc(100% - var(--header-height));
            opacity: 1;
            transition: opacity 0.2s;
        }

        .sidebar.collapsed .sidebar-content {
            opacity: 0;
            pointer-events: none;
        }

        /* --- Tree Menu (Категории) --- */
        .tree, .tree ul {
            list-style: none;
            padding: 0;
            margin: 0;
        }

        .tree ul {
            padding-left: 28px;
            display: none;
        }

        .tree ul.open {
            display: block;
        }

        .tree-item {
            display: flex;
            align-items: center;
            padding: 8px 16px 8px 12px;
            transition: background 0.2s;
        }

        .tree-item:hover {
            background: var(--background-blue-light);
        }

        .tree-link {
            color: var(--secondary);
            text-decoration: none;
            flex: 1;
            font-size: 14px;
            transition: color 0.2s;
        }

        .tree-item:hover .tree-link,
        .tree-link.active {
            color: var(--primary);
        }

        .tree-toggle {
            background: transparent;
            border: none;
            color: var(--secondary);
            cursor: pointer;
            width: 20px;
            height: 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-right: 6px;
            border-radius: 4px;
            padding: 0;
        }

        .tree-toggle:hover {
            background: var(--background-white);
            color: var(--primary);
        }

        .tree-toggle svg {
            width: 12px;
            height: 12px;
            transition: transform 0.2s;
            fill: currentColor;
        }

        .tree-toggle.open svg {
            transform: rotate(90deg);
        }

        /* --- Main Content --- */
        .main-content {
            flex: 1;
            padding: 40px;
            min-width: 0;
            position: relative;
        }

        .main-content hr {
            border-color: var(--spacer);
        }

        .main-content a {
            color: var(--blue);
        }

        .main-content a:hover {
            color: color-mix(in srgb, var(--blue) 80%, white);
        }
        .main-content a:hover > code {
            color: color-mix(in srgb, var(--blue) 80%, white);
        }

        .main-content blockquote {
            position: relative;
        }
        .main-content blockquote::before {
            content: "";
            position: absolute;
            left: -40px;
            top: 0; bottom: 0;
            width: 5px;
            height: 100%;
            background: var(--background);
            display: block;
        }

        .main-content h1,
        .main-content h2,
        .main-content h3,
        .main-content h4,
        .main-content h5,
        .main-content h6 {
            color: var(--primary);
            margin-top: 1em;
            margin-bottom: 0.5em;
            font-weight: 600;
        }

        .main-content table {
            width: 100%;
            border-collapse: collapse;
            margin: 1em 0;
            overflow-x: auto;
        }

        .main-content th, td {
            border: 1px solid var(--spacer);
            padding: 8px 12px;
            text-align: left;
        }

        .main-content th {
            background: var(--background);
        }

        .main-content img {
            max-width: 100%;
            height: auto;
            border-radius: 8px;
        }

        .main-content p {
            color: var(--secondary);
            line-height: 1.6;
        }

        .main-content pre {
            background: var(--background);
            padding: 15px;
            border-radius: 8px;
            overflow-x: auto;
            position: relative;
            margin: 1em 0;
        }

        .main-content code {
            color: var(--blue);
            font-family: 'Fira Code', monospace;
        }

        /* --- Footer --- */
        footer {
            flex-shrink: 0;
            border-top: 1px solid var(--spacer);
            padding: 30px 20px;
            display: flex;
            flex-direction: column;
            gap: 16px;
            background: var(--black);
            width: 100%;
        }

        .footer-row {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 20px;
            flex-wrap: wrap;
        }

        .footer-text {
            color: var(--secondary);
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .footer-text a {
            color: var(--primary);
            text-decoration: none;
            font-weight: 500;
            transition: color 0.2s;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .footer-text a:hover {
            color: var(--blue);
        }

        .social-links {
            display: flex;
            align-items: center;
            gap: 16px;
            margin-left: 12px;
        }

        .social-link {
            color: var(--secondary);
            transition: color 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
            text-decoration: none;
        }

        .social-link:hover {
            color: var(--blue);
        }

        .social-link svg {
            width: 20px;
            height: 20px;
            fill: currentColor;
        }

        .icon-external {
            width: 14px;
            height: 14px;
            fill: none;
            stroke: currentColor;
            stroke-width: 2;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        /* --- Mobile --- */
        @media (max-width: 768px) {
            .sidebar {
                position: absolute;
                height: 100%;
                background: var(--black);
            }
            .sidebar.collapsed {
                width: 0;
                pointer-events: none;
            }
            .sidebar.collapsed .sidebar-header {
                pointer-events: auto;
            }
            .main-content {
                width: 100vw;
                padding: 100px 20px 40px 20px;
            }
        }

        /* --- Error --- */
        .error-container {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 60px;
            max-width: 1200px;
            padding: 40px;
            width: 100%;
        }

        .error-image {
            flex: 1;
            display: flex;
            justify-content: flex-end;
            max-width: 50%;
        }

        .error-image img,
        .error-image svg {
            max-width: 100%;
            height: auto;
            object-fit: contain;
        }

        .error-content {
            flex: 1;
            max-width: 50%;
            font-family: "Manrope", sans-serif;
        }

        .error-content h1 {
            font-size: 42px;
            font-weight: 900;
            margin: 0 0 16px 0;
            color: var(--primary);
        }

        .error-content p {
            color: var(--secondary);
            font-size: 16px;
            line-height: 1.6;
            margin: 0 0 8px 0;
        }

        .error-content ul {
            color: var(--secondary);
            font-size: 16px;
            line-height: 1.6;
            margin: 8px 0 24px 0;
            padding-left: 24px;
        }

        .error-content li {
            margin-bottom: 6px;
        }

        /* Error Mobile */
        @media (max-width: 900px) {
            body {
                align-items: flex-start;
            }

            .error-container {
                flex-direction: column-reverse;
                gap: 20px;
                padding: 40px 20px 0 20px;
                height: 100vh;
                max-height: 100vh;
                width: 100%;
                overflow: hidden;
            }

            .error-content {
                max-width: 100%;
                flex: 0 0 auto;
                width: 100%;
                padding-bottom: 40px;
                display: flex;
                flex-direction: column;
                align-items: center;
            }

            .error-image {
                max-width: 100%;
                flex: 1 1 0;
                width: 100%;
                overflow: hidden;
                display: flex;
                align-items: flex-start;
                justify-content: center;
            }

            .error-image svg,
            .error-image img {
                width: 100%;
                max-width: 450px;
                height: auto;
            }

            .error-content p {
                text-align: left;
            }

            .error-content ul {
                text-align: left;
                display: inline-block;
            }

            .error-content h1 {
                text-align: center;
                font-size: 32px;
            }
        }
    </style>
</head>
<body>

