    <script>
        // Логика сворачивания сайдбара
        const toggleBtn = document.getElementById('sidebar-toggle');
        const sidebar = document.getElementById('sidebar');

        toggleBtn.addEventListener('click', () => {
            sidebar.classList.toggle('collapsed');
        });

        // Логика древовидного меню (категории)
        const treeToggles = document.querySelectorAll('.tree-toggle');

        treeToggles.forEach(btn => {
            btn.addEventListener('click', (e) => {
                // Предотвращаем срабатывание клика, если кнопка вложена во что-то еще
                e.stopPropagation();

                // Находим следующий <ul> в текущей ветке <li>
                const parentLi = btn.closest('li');
                const childUl = parentLi.querySelector('ul');

                if (childUl) {
                    btn.classList.toggle('open');
                    childUl.classList.toggle('open');
                }
            });
        });
    </script>
</body>
</html>